    local chosen = sel("mk_designs")
    local best, bs
    for _, id in ipairs(W.unlocked()) do
        local def = W.def(id)
        if def and (mode ~= "Chosen Designs" or chosen[def.display_name]) and #def.palette_roles <= #kits then
            local g = W.grid(def)
            local roles = table.clone(def.palette_roles)
            table.sort(roles, function(a, b) return (g.area[a] or 0) > (g.area[b] or 0) end)
            local assign, tot, wsum = {}, 0, 0
            for i, role in ipairs(roles) do
                local k = kits[i]
                assign[role] = k
                local a = g.area[role] or 0
                tot += a * G.vf(k.treatment) wsum += a
            end
            local value = (P.base_value(id) or 0) * (wsum > 0 and tot / wsum or 1)
            local score = value
            if mode == "New Designs First" and not made[id] and U and gcall(U.level, id) then score = score + 1e9 end
            if not bs or score > bs then best, bs = { id = id, def = def, assign = assign, value = value }, score end
        end
    end
    return best
end
function W.tuftAll(def, roleYarns)
    local radius, speed = W.tool(def, "tuft")
    local groups, order = {}, {}
    for _, role in ipairs(def.palette_roles) do
        local ry = roleYarns and roleYarns[role]
        local key = type(ry) == "table" and tostring(ry.treatment) or role
        if not groups[key] then groups[key] = { lead = role, roles = {} } order[#order + 1] = key end
        groups[key].roles[role] = true
    end
    for pass = 0, 2 do
        for _, key in ipairs(order) do
            local gp = groups[key]
            S.task = L["Tufting "] .. def.display_name
            local ok, why = W.stroke("tuft", gp.lead, W.path(def, gp.roles, radius, pass * radius * 0.6), speed)
            if not ok then return false, why end
        end
        local ok, why = W.advance()
        if ok then return true end
        if why ~= "tufting_incomplete" then return false, why end
    end
    return false, "tufting_incomplete"
end
function W.shaveOpen(def)
    local radius, speed = W.tool(def, "shave")
    for pass = 0, 2 do
        S.task = L["Shaving "] .. def.display_name
        local ok, why = W.stroke("shave", def.palette_roles[1], W.path(def, nil, radius, pass * radius * 0.6), speed)
        if not ok then return false, why end
        local ok2, why2 = W.advance()
        if ok2 then return true end
        if why2 ~= "shaving_incomplete" then return false, why2 end
    end
    return false, "shaving_incomplete"
end
function W.run(fn)
    W.busy = true W.flag.block = true
    local res = table.pack(pcall(fn))
    pcall(W.close)
    W.busy = false W.flag.block = false
    if not res[1] then say(L["Workbench: "] .. tostring(res[2]):sub(1, 60)) return false end
    return table.unpack(res, 2, res.n)
end
function W.shave(rug)
    return W.run(function()
        local def = W.def(rug.pattern_identifier) if not def then return false end
        local r, why = W.open(def.is_large and "large_table" or "table", rug.identifier)
        if not r then say(L["Can't open shaving table: "] .. tostring(why)) return false end
        if W.snap and W.snap.stage ~= "shaving" then return false end
        local ok, why2 = W.shaveOpen(def)
        if ok then S.made += 1 say(L["Rug finished: "] .. def.display_name) else say(L["Shaving stopped: "] .. tostring(why2)) end
        return ok
    end)
end
function W.craft(plan)
    return W.run(function()
        local station = plan and plan.def.is_large and "large_frame" or "frame"
        local r, why = W.open(station, 0)
        if not r then say(L["Can't open the frame: "] .. tostring(why)) return false end
        local snap = W.snap
        local def, roleYarns
        if snap.stage == "tufting" then
            def = W.def(snap.pattern_identifier)
            roleYarns = snap.role_yarns
        elseif snap.stage == "setup" then
            if not plan then return false end
            def = plan.def
            if snap.pattern_identifier ~= plan.id then
                local c = W.send({ command = "choose_design", pattern_identifier = plan.id, expected_revision = W.rev }, 4)
                if not (c and c.accepted) then say(L["Design refused: "] .. tostring(c and c.reason)) return false end
            end
            roleYarns = {}
            for _, role in ipairs(def.palette_roles) do
                local k = plan.assign[role]
                local c = W.send({ command = "choose_yarn", role = role, treatment = k.treatment }, 4)
                if not (c and c.accepted) then say(L["Yarn refused: "] .. tostring(c and c.reason)) return false end
                roleYarns[role] = { treatment = k.treatment }
            end
            local ok, why2 = W.advance()
            if not ok then say(L["Can't start tufting: "] .. tostring(why2)) return false end
        else
            return false
        end
        if not def then return false end
        local ok, why3 = W.tuftAll(def, roleYarns)
        if not ok then say(L["Tufting stopped: "] .. tostring(why3)) return false end
        S.task = L["Rug tufted"]
        return true
    end)
end
local D = { bad = {}, reserved = {} }
function D.stands()
