        local a = m:GetAttribute("display_rug")
        if a ~= nil and m:GetAttribute("asset_source") ~= "floor_rug" and m:FindFirstChildWhichIsA("BasePart", true) and m:GetPivot().Position.Magnitude > 5 and (D.bad[m.Name] or 0) < os.clock() then out[#out + 1] = { name = m.Name, model = m, rug = a } end
    end
