end
function D.candidates()
    local out = {}
    for _, r in ipairs(G.rugs()) do
        if r.stage == "finished" and not r.display_slot and not r.packaged and not r.favorite and not D.reserved[r.identifier] then out[#out + 1] = r end
    end
    table.sort(out, function(a, b) return (a.sale_price or 0) > (b.sale_price or 0) end)
    return out
end
function D.next()
    local c = D.candidates()
    if #c == 0 then return end
    for _, s in ipairs(D.stands()) do if s.rug == "" then return s, c[1] end end
    if not on("ds_swap") then return end
    local worst, wp
    for _, r in ipairs(G.rugs()) do
        if r.display_slot and (not wp or (r.sale_price or 0) < wp) then worst, wp = r, r.sale_price or 0 end
    end
    if worst and (c[1].sale_price or 0) > wp * 1.25 then
        for _, s in ipairs(D.stands()) do if s.name == worst.display_slot then return s, c[1], worst end end
    end
end
function D.place(s, rug, old)
