    if old then G.fire("display_action", "take", s.name, nil) task.wait(0.6) end
    G.fire("display_action", "place", s.name, rug.identifier)
    local t = os.clock()
    while os.clock() - t < 1.5 and s.model:GetAttribute("display_rug") == "" do task.wait(0.1) end
    if s.model:GetAttribute("display_rug") == "" then D.bad[s.name] = os.clock() + 120 LOG("display", "place failed on", s.name) else S.placed += 1 LOG("display", "placed rug", rug.identifier, "on", s.name, "$" .. tostring(rug.sale_price)) end
end
