function J.nextUpgrade()
    local cash, gems = G.cash(), G.gems()
    local keepC, keepG = val("up_keep", 0), val("up_keepg", 0)
    local function okKey(k) return (J.fail[k] or 0) < os.clock() end
    if on("up_tools") then
        local U = G.req("tools")
        if U then
            local data = gcall(U.decode, G.attr("tool_upgrades")) or {}
            local best, bp
            for _, id in ipairs({ "tuft", "shave" }) do
                local p = gcall(U.next_price, data, id)
                if p and (not bp or p < bp) and okKey("tool" .. id) then best, bp = id, p end
            end
            if best and cash - bp >= keepC then return { key = "tool" .. best, name = best == "tuft" and "Tufting Gun upgrade" or "Shaver upgrade", remote = "tool_upgrade", args = { best }, where = best == "tuft" and "frame" or "table" } end
        end
    end
    if on("up_slots") and Y.inv then
        local DU = G.req("disp")
        local p = DU and gcall(DU.next_slot_price, Y.inv)
        if p and cash - p >= keepC and okKey("slot") then return { key = "slot", name = "Yarn slot", remote = "dispenser_upgrade", args = { "slot" }, where = "dispenser" } end
        if on("up_merge") and DU and gcall(DU.merge_state, Y.inv) == "ready" and okKey("merge") then return { key = "merge", name = "Dispenser merge", remote = "dispenser_upgrade", args = { "merge" }, where = "dispenser" } end
    end
    if on("up_designs") then
        local U = G.req("unlocks") local C = G.req("catalog")
        if U and C then
            local have = G.list(G.attr("unlocked_designs"))
            local made = G.list(G.attr("designs_made"))
            local best, bp
            for _, d in ipairs(C.all) do
                local id = d.pattern_identifier
                if not gcall(U.is_unlocked, have, id) and okKey("d" .. id) then
                    local p
                    if gcall(U.is_seasonal, id) then
                        if on("up_season") and not (d.is_large and not W.hasLarge()) then p = gcall(U.seasonal_price, id) end
                    elseif gcall(U.is_large, id) then
                        if W.hasLarge() then local lv = gcall(U.large_level, id) if lv and gcall(U.is_large_level_open, made, lv, true) then p = gcall(U.large_price, id) end end
                    else
                        local lv = gcall(U.level, id)
                        if lv and gcall(U.is_level_open, made, lv) then p = gcall(U.price, id) end
                    end
                    if p and (not bp or p < bp) then best, bp = d, p end
                end
            end
            if best and cash - bp >= keepC then return { key = "d" .. best.pattern_identifier, name = best.display_name .. " design", remote = "unlock_design", args = { best.pattern_identifier } } end
        end
    end
    local want = sel("up_studio")
    if next(want) then
        local SU = G.req("studio")
        if SU then
            local data = gcall(SU.decode, G.attr("studio_upgrades")) or {}
            for _, pair in ipairs(J.STUDIO) do
                if want[pair[1]] and okKey("s" .. pair[2]) then
                    local up = gcall(SU.upgrade, pair[2])
                    local tier = up and gcall(SU.next_tier, data, up)
                    if tier and tier.cost and gems - tier.cost >= keepG then return { key = "s" .. pair[2], name = pair[1], remote = "buy_studio_upgrade", args = { pair[2] } } end
                end
            end
        end
    end
end
