function O.matches(o, r)
    if r.stage ~= "finished" or r.package or r.packing or r.pattern_identifier ~= o.pattern_identifier or type(r.treatments) ~= "table" then return false end
    if #r.treatments ~= #o.treatments then return false end
    for i, t in ipairs(o.treatments) do if r.treatments[i] ~= t then return false end end
    return true
end
function O.rugFor(o, taken)
    for _, r in ipairs(G.rugs()) do if not (taken and taken[r.identifier]) and O.matches(o, r) and not r.favorite then return r end end
end
function O.kitsFor(o, kits)
    local def = W.def(o.pattern_identifier)
    if not def or #def.palette_roles ~= #o.treatments then return end
    local used, assign = {}, {}
    for i, role in ipairs(def.palette_roles) do
        local want = o.treatments[i]
        local pick
        for _, k in ipairs(kits) do if not used[k] and k.treatment == want then pick = k break end end
        if not pick then return end
        used[pick] = true
        assign[role] = pick
    end
    return { id = o.pattern_identifier, def = def, assign = assign, value = 0, order = o.identifier }
end
function O.reserve()
    local res = {}
    for _, o in ipairs(O.list) do
        if o.status == "accepted" then local r = O.rugFor(o, res) if r then res[r.identifier] = true end end
    end
    D.reserved = res
    return res
end
function O.packSpot()
    local sh = G.shop()
    return sh and G.find(sh, "workshop.packing_station.work_surface.packing_prompt_anchor")
end
function O.cabinet()
    local sh = G.shop()
    local c = sh and sh:FindFirstChild("parcel_cabinet")
    if not c then return end
    local p = c:FindFirstChild("parcel_prompt", true)
    return p and p.Parent or c
end
function O.pack(o, rug)
    local spot = O.packSpot()
    if not spot then
        if G.cash() >= 100 then G.go("showroom") G.ask("unlock_packing") task.wait(1) spot = O.packSpot() end
        if not spot then return false, "packing locked" end
    end
    if rug.display_slot then G.fire("display_action", "take", rug.display_slot, nil) task.wait(0.8) end
    if not G.tpTo(G.pos(spot), "pack", 3, G.find(G.shop(), "workshop.packing_station")) then return false, "no spot" end
    S.task = L["Packing an order"]
    local b = G.ask("packing_request", { action = "begin", order = o.identifier })
    if not (type(b) == "table" and b.accepted and b.token) then return false, b and b.reason end
    local tok, rev = b.token, 0
    local steps = { { "wall", "left" }, { "wall", "right" }, { "wall", "front" }, { "wall", "back" }, { "roll" }, { "insert" }, { "flap", "left" }, { "flap", "right" }, { "flap", "front" }, { "flap", "back" }, { "tape" } }
    task.wait(0.4)
    for _, s in ipairs(steps) do
        local r2
        for try = 1, 3 do
            r2 = G.ask("packing_request", { action = s[1], side = s[2] or "", token = tok, revision = rev })
            if type(r2) == "table" and r2.accepted then break end
            task.wait(0.4 * try)
        end
        if not (type(r2) == "table" and r2.accepted) then G.ask("packing_request", { action = "close", token = tok }) return false, (r2 and r2.reason) or ("step " .. s[1]) end
        rev = (r2.state and r2.state.revision) or rev + 1
        if r2.complete then LOG("order", "packed order", o.identifier) return true end
        task.wait(0.35)
    end
    return true
end
function O.ship(rug)
    local cab = O.cabinet()
    if not cab then return false end
    if not G.tpTo(G.pos(cab), "showroom", 3, G.shop():FindFirstChild("parcel_cabinet")) then return false, "no spot" end
    S.task = L["Shipping a parcel"]
    local res = G.ask("parcel_delivery", rug.identifier, tonumber(G.attr("shop_index")))
    return type(res) == "table" and res.accepted, res and res.reason
end
