    for _, r in ipairs(G.rugs()) do if r.package and not r.packing then J.od = { kind = "ship", rug = r } return true end end
    local taken = {}
    for _, o in ipairs(O.list) do
        if o.status == "accepted" then
            local r = O.rugFor(o, taken)
            if r then J.od = { kind = "pack", order = o, rug = r } return true end
        end
    end
    local open = 0
    for _, o in ipairs(O.list) do if o.status == "accepted" then open += 1 end end
    if open < val("od_max", 2) then
        local kits = Y.freeKits(Y.inv)
        for _, o in ipairs(O.list) do
            if o.status == "offered" and O.kitsFor(o, kits) then J.od = { kind = "accept", order = o } return true end
        end
    end
    J.odBlock = os.clock() + 3
    return false
end, function()
    local t = J.od
    if t.kind == "ship" then
        local ok, why = O.ship(t.rug)
        if ok then say(L["Order delivered"]) S.orders = (S.orders or 0) + 1 else J.odBlock = os.clock() + 15 say(L["Delivery: "] .. tostring(why)) end
    elseif t.kind == "pack" then
        local ok, why = O.pack(t.order, t.rug)
        if not ok then J.odBlock = os.clock() + 15 say(L["Packing: "] .. tostring(why)) end
    else
        G.fire("online_orders", "accept", t.order.identifier)
        say(L["Accepted an order"])
        task.wait(1)
        pcall(G.fire, "online_orders", "request")
        task.wait(0.5)
    end
end)
