function O.craftPlan(kits)
    if not on("od_on") then return end
    local taken = {}
    for _, o in ipairs(O.list) do
        if o.status == "accepted" then
            local have = O.rugFor(o, taken)
            if have then taken[have.identifier] = true
            else
                local p = O.kitsFor(o, kits)
                if p then return p end
            end
        end
    end
end
