function F.mod() return G.req("furn") end
function F.owned(n) return table.find(G.list(G.attr("shop_furniture")), n) ~= nil end
function F.hired(id) return tostring(G.attr("employees") or ""):find(id, 1, true) ~= nil end
function F.at(n)
