function F.nextFurniture()
    local okKey = function(k) return (J.fail[k] or 0) < os.clock() end
    local keep = val("up_keep", 0)
    local want = sel("up_items")
    for _, label in ipairs({ "Display Stands", "Rug Cabinet", "Apprentice Station", "Tip Jar" }) do
        if want[label] then
            for _, n in ipairs(F.ORDER[label]) do
                if not F.owned(n) then
                    local at = F.at(n)
                    local price = F.price(n)
                    if at and price and okKey("f" .. n) and G.cash() - price >= keep then
                        return { key = "f" .. n, name = n:gsub("_", " "), remote = "buy_furniture", args = { n }, at = at }
                    end
                    break
                end
            end
        end
    end
end
function F.nextHire()
    local okKey = function(k) return (J.fail[k] or 0) < os.clock() end
    local keep = val("up_keep", 0)
    local hire = sel("up_hire")
    for _, h in ipairs(F.HIRE) do
        if hire[h[1]] and not F.hired(h[2]) and okKey("h" .. h[2]) and G.cash() - h[3] >= keep and (not h[4] or F.owned(h[4])) then
            return { key = "h" .. h[2], name = h[1], remote = "employee_action", args = { "hire", h[2] }, at = h[4] and F.at(h[4]) or nil, where = (not h[4]) and "register" or nil }
        end
    end
end
