function R.codes()
    local C = G.req("codes")
    local got = 0
    if not (C and C.list) then return 0 end
    for code, info in pairs(C.list) do
        if not R.codesDone[code] and info.active ~= false then
            R.codesDone[code] = true
            local r = G.ask("redeem_code", code)
            if type(r) == "table" and r.accepted then got += 1 end
            task.wait(0.6)
        end
    end
    return got
end
function R.claim(force)
    local got = {}
    if R.due("daily", 600, force) then local r = G.ask("daily_reward_request") if type(r) == "table" and r.accepted then got[#got + 1] = "daily reward" end end
    if R.due("free", 300, force) and G.attr("free_reward_claimed") ~= true then local r = G.ask("free_reward_request") if type(r) == "table" and r.accepted then got[#got + 1] = "free reward" end end
    if R.due("book", 90, force) then
        local ids, seen = {}, {}
        for _, id in ipairs(G.list(G.attr("designs_made"))) do if not seen[id] then seen[id] = true ids[#ids + 1] = id end end
        for _, id in ipairs(G.list(G.attr("unlocked_designs"))) do if not seen[id] then seen[id] = true ids[#ids + 1] = id end end
        local n = 0
        for _, id in ipairs(ids) do
            local r = G.ask("claim_collection_reward", id)
            if type(r) == "table" and r.accepted then n += 1 end
            task.wait(0.25)
        end
        if n > 0 then got[#got + 1] = n .. " design rewards" end
    end
    if R.due("codes", 1800, force) then local n = R.codes() if n > 0 then got[#got + 1] = n .. L[" codes"] end end
    if #got > 0 then say(L["Claimed "] .. table.concat(got, ", ")) end
end
