            if #LOGBUF ~= lastN or (LOGBUF[#LOGBUF] ~= X.lastLine) then
                lastN = #LOGBUF X.lastLine = LOGBUF[#LOGBUF]
                pcall(function() if makefolder and not isfolder("COMBO_WICK_RUGS") then makefolder("COMBO_WICK_RUGS") end writefile("COMBO_WICK_RUGS/debug_log.txt", table.concat(LOGBUF, "\n")) end)
            end
            task.wait(3)
        end
    end)
end
do
    local pg = lp:WaitForChild("PlayerGui")
    local function hookNotice(g)
        if g.Name ~= "notice" then return end
        local function watch(d)
            if d:IsA("TextLabel") then
                track(d:GetPropertyChangedSignal("Text"):Connect(function() if d.Text ~= "" then LOG("toast", (d.Text:gsub("<[^>]+>", ""))) end end))
                if d.Text ~= "" then LOG("toast", (d.Text:gsub("<[^>]+>", ""))) end
            end
        end
        for _, d in ipairs(g:GetDescendants()) do watch(d) end
        track(g.DescendantAdded:Connect(watch))
    end
    for _, g in ipairs(pg:GetChildren()) do hookNotice(g) end
    track(pg.ChildAdded:Connect(hookNotice))
end
